/**
 * Argument parsing per the README.
 *
 * `--retry <n>` sets the retry count (default 0). `--retry` without a value is
 * an error.
 */
export function parseArgs(argv) {
  let retries = 0
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === '--retry') {
      const value = argv[i + 1]
      if (value === undefined) {
        throw new Error('--retry requires a value')
      }
      const parsed = Number(value)
      if (!Number.isInteger(parsed) || parsed < 0) {
        throw new Error('--retry must be a non-negative integer')
      }
      retries = parsed
      i += 1
    }
  }
  return { retries }
}

/**
 * Retry logic per the README.
 *
 * `retryWithBackoff(fn, retries)` calls `fn()` and, on a thrown transient
 * error (`code === 'ETIMEDOUT'` or `'ECONNRESET'`), retries up to `retries`
 * times with a short delay. Non-transient errors propagate immediately.
 */

const TRANSIENT_CODES = new Set(['ETIMEDOUT', 'ECONNRESET'])
const RETRY_DELAY_MS = 5

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

const isTransient = (error) =>
  error !== null &&
  typeof error === 'object' &&
  TRANSIENT_CODES.has(error.code)

export async function retryWithBackoff(fn, retries) {
  let attempts = 0
  for (;;) {
    try {
      return await fn()
    } catch (error) {
      if (!isTransient(error) || attempts >= retries) {
        throw error
      }
      attempts += 1
      await sleep(RETRY_DELAY_MS)
    }
  }
}

