args.new_string:
test('retry: gives up after retries are exhausted', async () => {
  await assert.rejects(() => retryWithBackoff(() => Promise.reject(transient('timeout')), 2))
})

test('retry: does not retry non-transient errors', async () => {
  let calls = 0
  const error = new Error('bad request')
  error.code = 'EINVAL'
  await assert.rejects(
    () =>
      retryWithBackoff(() => {
        calls += 1
        return Promise.reject(error)
      }, 3),
    /bad request/
  )
  assert.equal(calls, 1)
})

test('retry: >= 99% success rate under 30% packet loss with retries=3', async () => {
  // Deterministic PRNG (LCG) so the acceptance check is reproducible.
  let state = 0x2f6e2b1
  const random = () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0
    return state / 4294967296
  }

  const LOSS = 0.3
  const RUNS = 2000
  const attempt = () => {
    if (random() < LOSS) {
      const error = new Error('connection reset by peer')
      error.code = 'ECONNRESET'
      return Promise.reject(error)
    }
    return Promise.resolve('ok')
  }

  let failures = 0
  for (let i = 0; i < RUNS; i += 1) {
    try {
      await retryWithBackoff(attempt, 3)
    } catch {
      failures += 1
    }
  }

  assert.ok(
    failures / RUNS < 0.01,
    `failure rate ${(failures / RUNS).toFixed(4)} >= 1% under 30% packet loss`
  )
})

