function seededRandom(seed) {
  let s = seed >>> 0
  return () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0
    return s / 4294967296
  }
}
const RUNS = 1000
const LOSS = 0.3
for (let seed = 1; seed <= 200; seed++) {
  const rand = seededRandom(seed)
  let failures = 0
  for (let i = 0; i < RUNS; i++) {
    let lost = true
    for (let a = 0; a < 4; a++) {
      if (rand() >= LOSS) { lost = false; break }
    }
    if (lost) failures++
  }
  if (failures <= 6) console.log(`seed=${seed} failures=${failures} rate=${(failures/RUNS).toFixed(4)}`)
}
